/// حالات يُقارن مخرجها العددي بسماحية 2 ULP في
/// بوابة الخلفية الأصلية وحدها (c_parity.rs) — لا
/// تسري على parity_gate ولا على أي حالة غير معلَّمة.
/// السبب (اجتماع 82 §97): تباين libm في الدوال
/// المتسامية عبر المنصات (exp غير ملزم التقريب
/// الصحيح في IEEE 754) والصيغة مطابقة حرفيا في
/// الطرفين — فالفرق حتى 2 ULP في الخانة الأخيرة
/// ليس خطأ منطق في نيفا. تُعلَّم هنا حالة واحدة
/// فقط في هذه الدفعة: «توزيعات-ج10-أساسية».
pub static FLOAT_TOLERANT_CASES: &[&str] = &["توزيعات-ج10-أساسية"];

