/// عشر): كل استدعاء دالة في المفسر يجري في إطار
/// محليات خاص به، مطابقا للمترجم — فلا يتسرب
/// محلي مساعد إلى متصل أبدا، ولا يسمّم اسم حر.
/// الصيغة: (الاسم، سطور البرنامج الرئيسي، ملفات
/// الوحدات بجانبه). كل حالة كانت تطبع في المفسر
/// غير ما يطبعه المترجم قبل العزل، وتطابقت بعده.
pub static LEAK_CASES: &[(&str, &[&str], &[(&str, &str)])] = &[
    // النمط 1: محلي في وحدة يُرى من خارجها بعد
    // الاستدعاء — كان المفسر يطبع «داخلية».
    (
        "تسرب-وحدة-1",
        &[
            "استورد م",
            "دالة خارجية():",
            "  س = \"خارجية\"",
            "  م.داخلية()",
            "  ارجع س",
            "اطبع خارجية()",
        ],
        &[(
            "م.نيفا",
            "صدر داخلية\nدالة داخلية():\n  س = \"داخلية\"\n  ارجع س\n",
        )],
    ),
    // النمط 2: تسميم الاسم الحر عبر سلسلة المتصل —
    // اسم `نص` المستورَد في المتصل كان يظلل
    // المدمج `نص` داخل جرّب، فيخطئ المفسر بـ
    // «القيمة وحدة ليست دالة».
    (
        "تسميم-متصل-2",
        &["استورد نص", "استورد وحدة", "اطبع وحدة.جرّب()"],
        &[
            ("نص.نيفا", "صدر شيء\nشيء = ١\n"),
            (
                "وحدة.نيفا",
                "صدر جرّب\nدالة جرّب():\n  ارجع نص(٤٢)\n",
            ),
        ],
    ),
    // النمط 3: مساعد في وحدة يكتب فوق محلي المتصل
    // الذي يحمل الاسم نفسه (المستدعى ← المتصل) —
    // كان المفسر يطبع ١ بدل ٣.
    (
        "تسرب-مساعد-3",
        &[
            "استورد مساعد3",
            "دالة متصل():",
            "    عداد = ٠",
            "    س = ٠",
            "    بينما عداد < ٣:",
            "        مساعد3.مساعد(\"س\")",
            "        س = س + ١",
            "        عداد = عداد + ١",
            "    ارجع س",
            "اطبع متصل()",
        ],
        &[(
            "مساعد3.نيفا",
            "صدر مساعد\nدالة مساعد(نص):\n    عداد = ٥\n    ارجع عداد\n",
        )],
    ),
    // النمط 4 (الفجوة 18): التسرب داخل ملف وحدة
    // واحد بين دالتين فيه تشتركان في اسم محلي —
    // كان المفسر يطبع ١ بدل ٣.
    (
        "تسرب-داخل-وحدة-4",
        &["استورد وحدة", "اطبع وحدة.متصل()"],
        &[(
            "وحدة.نيفا",
            "صدر مساعد\nصدر متصل\n\nدالة مساعد(نص):\n    عداد = ٥\n    ارجع عداد\n\nدالة متصل():\n    عداد = ٠\n    س = ٠\n    بينما عداد < ٣:\n        مساعد(\"س\")\n        س = س + ١\n        عداد = عداد + ١\n    ارجع س\n",
        )],
    ),
];
